        ["Import settings..."] = "UI_PZOpt_2123",
        ["Copies the settings of the Optimizations, Enhancements and Profiler tabs to the clipboard as text (the ones that differ from the build's defaults, as the controls show them now, changes not applied yet included) and saves the same text to Zomboid/pzopt/settings-export.ini. Import settings... reads it back, here or on another PC."] = "UI_PZOpt_2124",
        ["Sets the controls of the Optimizations, Enhancements and Profiler tabs from exported text: paste it into the box (it starts with the clipboard, or with Zomboid/pzopt/settings-export.ini when the clipboard holds no settings). Settings the text does not list go back to the build's defaults. Nothing is saved until you press Apply or Accept."] = "UI_PZOpt_2125",
